template <
  typename T,
  typename std::enable_if<
    std::is_base_of<T, types::ISomething>::value
  >::type*
>
std::pair<
  common::optional<std::shared_ptr<T> >,
  common::optional<DeserializationError>
> SomethingFromSequence(
  xml_common::ReaderMergingText& reader
) {
  // region Initialization

  common::optional<types::StructuralUnion> the_structural_property;

  common::optional<types::MixedUnion> the_mixed_property;

  common::optional<types::ModelTypedUnion> the_model_typed_property;

  common::optional<std::vector<types::StructuralUnion> > the_list_structural_property;

  common::optional<std::vector<types::MixedUnion> > the_list_mixed_property;

  common::optional<std::vector<types::ModelTypedUnion> > the_list_model_typed_property;

  common::optional<
    std::tuple<
      types::StructuralUnion,
      types::MixedUnion,
      types::ModelTypedUnion
    >
  > the_tuple_property;

  common::optional<types::StructuralUnion> the_optional_structural_property;

  common::optional<types::MixedUnion> the_optional_mixed_property;

  common::optional<types::ModelTypedUnion> the_optional_model_typed_property;

  // endregion Initialization

  common::optional<DeserializationError> error(
    ReadProperties<
      properties::kPropertyCountOfSomething
    >(
      reader,
      properties::kMapOfSomething,
      L"ISomething",
      [&](
        properties::OfSomething property
      ) -> common::optional<DeserializationError> {
        switch (property) {
          case properties::OfSomething::kStructuralProperty:
            return ReadInto(
              the_structural_property,
              StructuralUnionFromElement(reader)
            );
          case properties::OfSomething::kMixedProperty:
            return ReadInto(
              the_mixed_property,
              MixedUnionFromElement(reader)
            );
          case properties::OfSomething::kModelTypedProperty:
            return ReadInto(
              the_model_typed_property,
              ModelTypedUnionFromElement(reader)
            );
          case properties::OfSomething::kListStructuralProperty:
            return ReadInto(
              the_list_structural_property,
              DeserializeList<
                types::StructuralUnion
              >(
                reader,
                StructuralUnionFromElement
              )
            );
          case properties::OfSomething::kListMixedProperty:
            return ReadInto(
              the_list_mixed_property,
              DeserializeList<
                types::MixedUnion
              >(
                reader,
                MixedUnionFromElement
              )
            );
          case properties::OfSomething::kListModelTypedProperty:
            return ReadInto(
              the_list_model_typed_property,
              DeserializeList<
                types::ModelTypedUnion
              >(
                reader,
                ModelTypedUnionFromElement
              )
            );
          case properties::OfSomething::kTupleProperty:
            return ReadInto(
              the_tuple_property,
              DeserializeTuple3<
                types::StructuralUnion,
                types::MixedUnion,
                types::ModelTypedUnion
              >(
                reader,
                StructuralUnionFromElement,
                MixedUnionFromElement,
                ModelTypedUnionFromElement
              )
            );
          case properties::OfSomething::kOptionalStructuralProperty:
            return ReadInto(
              the_optional_structural_property,
              StructuralUnionFromElement(reader)
            );
          case properties::OfSomething::kOptionalMixedProperty:
            return ReadInto(
              the_optional_mixed_property,
              MixedUnionFromElement(reader)
            );
          case properties::OfSomething::kOptionalModelTypedProperty:
            return ReadInto(
              the_optional_model_typed_property,
              ModelTypedUnionFromElement(reader)
            );
          default:
            throw UnexpectedPropertyLiteralError(
              "properties::OfSomething",
              property
            );
        }
      }
    )
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<T>
    >(
      std::move(*error)
    );
  }

  // region Check required properties

  if (!the_structural_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property structuralProperty is missing"
    );
  }

  if (!the_mixed_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property mixedProperty is missing"
    );
  }

  if (!the_model_typed_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property modelTypedProperty is missing"
    );
  }

  if (!the_list_structural_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property listStructuralProperty is missing"
    );
  }

  if (!the_list_mixed_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property listMixedProperty is missing"
    );
  }

  if (!the_list_model_typed_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property listModelTypedProperty is missing"
    );
  }

  if (!the_tuple_property.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property tupleProperty is missing"
    );
  }

  // endregion Check required properties

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<T>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::Something(
        std::move(*the_structural_property),
        std::move(*the_mixed_property),
        std::move(*the_model_typed_property),
        std::move(*the_list_structural_property),
        std::move(*the_list_mixed_property),
        std::move(*the_list_model_typed_property),
        std::move(*the_tuple_property),
        std::move(the_optional_structural_property),
        std::move(the_optional_mixed_property),
        std::move(the_optional_model_typed_property)
      )
    ),
    common::nullopt
  );
}

template <typename ValueT, typename FromElementT>
common::expected<
  ValueT,
  DeserializationError
> DeserializeFrom(
  std::istream& is,
  const ReadingOptions& options,
  const FromElementT& from_element
) {
  xml_common::ReaderMergingText reader(
    is,
    options.additional_attributes,
    options.buffer_size
  );

  reader.Initialize();
  if (reader.node().kind() == xml_common::NodeKind::Error) {
    return common::make_unexpected(
      DeserializationErrorFromReader(reader)
    );
  }

  common::optional<ValueT> instance;
  common::optional<DeserializationError> error;

  std::tie(
    instance,
    error
  ) = from_element(reader);

  if (error.has_value()) {
    return common::make_unexpected(
      std::move(*error)
    );
  }

  error = SkipWhitespace(reader);
  if (error.has_value()) {
    return common::make_unexpected(
      std::move(*error)
    );
  }

  error = CheckReaderAtEof(reader);
  if (error.has_value()) {
    return common::make_unexpected(
      std::move(*error)
    );
  }

  return std::move(*instance);
}

